    if (!arg.startsWith("--")) {
      for (const ch of arg.slice(1)) {
        if (ch !== "s") return null;
      }
      continue;
    }
    const option = normalizeTtyLongOption(arg);
    if (option.includes("=") || !TTY_LONG_OPTIONS.includes(option.slice(2))) return null;
