        measure = 0;
        lineHasToken = false;
        if (mode === "bytes") next = tokenLength;
        else if (mode === "characters") next = 1;
        else if (tokenLength === 1 && (byte === 0x08 || byte === 0x0d)) next = 0;
        else if (tokenLength === 1 && byte === 0x09) next = 8;
        else if (tokenLength === 1 && byte === 0x0c) next = 1;
