    mode: 0,
    size: 0,
    blocks: 0,
    ino: 0,
    nlink: 0,
    uid: 0,
    gid: 0,
    isFile: () => isType(8),
    isDirectory: () => isType(4),
    isBlockDevice: () => isType(6),
    isCharacterDevice: () => isType(2),
    isSymbolicLink: () => isType(10),
