    const line = raw.replace(/\n$/, "");
    const section = nlSection(line, delimiter);
    if (section) {
      if (!(opts.p || opts["no-renumber"])) number = start;
      currentSection = section;
      blankRun = 0;
      return "\n";
    }
    const blank = raw === "\n";
    blankRun = blank ? blankRun + 1 : 0;
