          emit(base64Alphabet.charCodeAt((triple >>> 18) & 63));
          emit(base64Alphabet.charCodeAt((triple >>> 12) & 63));
          emit(base64Alphabet.charCodeAt((triple >>> 6) & 63));
          emit(base64Alphabet.charCodeAt(triple & 63));
