      source: mountInfo.source,
      name: mountInfo.source,
      total: inodeMode ? inodeTotal : sizeTotal,
      used: inodeMode ? inodeUsed : sizeUsed,
      avail: inodeMode ? inodeAvail : sizeAvail,
      sizeTotal,
      sizeUsed,
      sizeAvail,
      inodeTotal,
      inodeUsed,
