    while (remaining > 0) {
      const { bytesRead } = await handle.read(buffer, 0, Math.min(buffer.length, remaining), null);
      if (bytesRead === 0) break;
      stdout(buffer.subarray(0, bytesRead));
      remaining -= bytesRead;
    }
